    "gate": {
      "title": "The 5-Point Empirical Verification Gate",
      "sub": "Zero-Hallucination & Defensive Architecture Manifesto",
      "intro": "Many software components silently fail or falsely claim success when a step goes wrong. My core engineering principle is simple: no feature or AI agent is allowed to declare success without live, verifiable proof. Five non-negotiable rules govern every codebase I ship:",
      "points": [
        {
          "num": "1",
          "t": "Empirical Evidence Mandate (Zero Speculation)",
          "d": "No task or feature is declared complete without exit code 0, 0 compiler errors, exact file paths, line ranges, and live runtime verification. Speculative language (probably, seems like) is strictly banned."
        },
        {
          "num": "2",
          "t": "Defensive State Bounds Validation",
          "d": "Mandatory validation guards checking for NaN, Infinity, and out-of-bounds values prior to mutating spatial transforms, physics vectors, or financial ledger balances."
        },
        {
          "num": "3",
          "t": "Hot-Loop Zero-GC Invariant",
          "d": "In high-frequency loops (Update methods, frame diffing, audio streaming), object instantiations (new), string concatenations, and LINQ queries are banned, with pre-cached Property IDs."
        },
        {
          "num": "4",
          "t": "Resilient Watchdog Recovery",
          "d": "Universal watchdog timers (e.g. 15-second timeouts) guarding WebSockets, browser speech services, and asynchronous message queues to prevent frozen UI states."
        },
        {
          "num": "5",
          "t": "Fail-Closed Security & HMAC Logging",
          "d": "Credentials are never logged or exposed in prompts; variable inspection is restricted to name and length only; and all actions are recorded in cryptographically chained HMAC ledgers."
        }
      ]
    },
