    "about": {
      "title": "Resumen Ejecutivo — Claro para Directivos, Preciso para Ingenieros",
      "sub": "Uniendo modelos de IA avanzados con ingeniería de software de producción",
      "p1": "En términos claros, diseño y entrego <b>sistemas que automatizan procesos complejos con fiabilidad comprobable</b>: desde copilotos de escritorio que ven la pantalla y traducen audio en menos de 250 ms hasta suites contables en la nube y fábricas de software con agentes. A nivel técnico me especializo en <b>microservicios distribuidos, máquinas de estados deterministas, pipelines multimodales en GPU y seguridad verificable</b>: colas con prioridad Celery (0/3/9), búsqueda vectorial Qdrant, registros criptográficos HMAC-SHA256 y bucles Zero-Allocation en C#.",
      "p2": "En los últimos años he diseñado y desplegado <b>18 sistemas completos de principio a fin</b>: UniversalSystem (fábrica IA de 17 microservicios), clon empresarial de Zoho Books (118 páginas estáticas), Universal Doc Factory (69K líneas con verificación de citas), copilotos autónomos para Windows, traductores CUDA en vivo, plataformas de aprendizaje de idiomas y videojuegos publicados comercialmente.",
      "cards": [
        {
          "t": "1. Enjambres Multi-Agente y Automatización",
          "d": "Varios agentes coordinados investigan, generan código, prueban y verifican automáticamente en lugar de scripts frágiles. Arquitectura: colas con prioridad Celery (0/3/9), aprobaciones humanas, auditoría HMAC-SHA256 y validación literal de citas."
        },
        {
          "t": "2. IA Multimodal de Voz y Visión en Vivo (< 250 ms)",
          "d": "Asistentes de escritorio que capturan audio interno o pantallas 1440p y responden al instante. Basados en WASAPI Loopback, faster-whisper en CUDA FP16, WebSockets Gemini Live y filtrado OpenCV SSIM/MSE (>75 % ahorro de tokens)."
        },
        {
          "t": "3. Software Empresarial, ERP y Finanzas",
          "d": "Contabilidad de partida doble en la nube, facturación multimoneda y portales de proyectos listos para equipos globales. Con Next.js 15 (118 páginas, 20 idiomas sin fugas), C# .NET 10 Clean Architecture, Transactional Outbox y tipografía RTL."
        },
        {
          "t": "4. Motores de Juego, Física y Rendimiento Zero-GC",
          "d": "Juegos 3D y 2D optimizados para mantener 60 FPS estables incluso en móviles económicos. Implementado con bucles Zero-GC vía Span<T>/Memory<T>, compilación Burst / IL2CPP ARM64, caché de shaders y 222 guardas contra NaN/Infinity."
        }
      ]
    },
