    "gate": {
      "title": "La Compuerta Empírica de 5 Puntos",
      "sub": "Manifiesto de Arquitectura Defensiva y Cero Alucinaciones",
      "intro": "Muchos sistemas fallan en silencio o reportan éxito sin comprobar el resultado real. Mi principio central es claro: ningún software ni agente de IA puede declarar una tarea completada sin pruebas verificables en ejecución. Cinco reglas obligatorias rigen cada sistema que construyo:",
      "points": [
        {
          "num": "1",
          "t": "Mandato de Evidencia Empírica (Cero Especulación)",
          "d": "Nada se da por terminado sin código de salida 0, cero errores de compilación, rutas exactas de archivo y verificación en ejecución. Queda prohibido especular con 'debería funcionar'."
        },
        {
          "num": "2",
          "t": "Validación Defensiva de Límites de Estado",
          "d": "Guardas obligatorias contra NaN, Infinity y valores fuera de rango antes de modificar transformaciones físicas, coordenadas o balances contables."
        },
        {
          "num": "3",
          "t": "Regla Zero-GC en Bucles Críticos",
          "d": "En bucles de alta frecuencia (Update, comparación de vídeo y audio en vivo) se prohíben nuevas asignaciones (new), concatenaciones de texto y LINQ, precargando identificadores de shaders."
        },
        {
          "num": "4",
          "t": "Recuperación Resiliente mediante Vigilantes",
          "d": "Temporizadores estrictos (como límites de 15 segundos) supervisan WebSockets, reconocimiento de voz y colas asíncronas para que la interfaz nunca quede congelada."
        },
        {
          "num": "5",
          "t": "Seguridad Fail-Closed y Trazabilidad HMAC",
          "d": "Las credenciales jamás se imprimen en registros — solo se verifica su nombre y longitud — y toda operación queda sellada en libros criptográficos HMAC encadenados."
        }
      ]
    },
